package cn.minidayz.patcher;
import android.content.*;import android.util.Base64;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.spec.AlgorithmParameterSpec;
/** Keys never enter diagnostic reports or exported modules. AndroidKeyStore AES-GCM. */
public final class AiSettings {
 final SharedPreferences p;public AiSettings(Context c){p=c.getSharedPreferences("ai_private",0);}
 public String endpoint(){return p.getString("endpoint","https://api.openai.com/v1/chat/completions");}public String model(){return p.getString("model","");}public int limit(){return p.getInt("limit",2048);}
 private java.security.Key key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);String alias="mdz.ai.api.v1";if(!s.containsAlias(alias)){Class<?> b=Class.forName("android.security.keystore.KeyGenParameterSpec$Builder");Object builder=b.getConstructor(String.class,int.class).newInstance(alias,3);b.getMethod("setBlockModes",String[].class).invoke(builder,new Object[]{new String[]{"GCM"}});b.getMethod("setEncryptionPaddings",String[].class).invoke(builder,new Object[]{new String[]{"NoPadding"}});KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init((AlgorithmParameterSpec)b.getMethod("build").invoke(builder));g.generateKey();}return s.getKey(alias,null);}
 public String secret()throws Exception{String v=p.getString("key","");if(v.length()==0)return "";byte[] all=Base64.decode(v,0);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,all,0,12));return new String(c.doFinal(all,12,all.length-12),"UTF-8");}
 public String protocol(){return p.getString("protocol","auto");}public String tokenField(){return p.getString("token_field","max_tokens");}public String session(){String v=p.getString("session","");if(v.length()==0){v=java.util.UUID.randomUUID().toString();p.edit().putString("session",v).commit();}return v;}public void newSession(){p.edit().putString("session",java.util.UUID.randomUUID().toString()).commit();}
 public void save(String url,String model,String secret,int limit)throws Exception{ApiProtocol.endpoint(url,"auto");FilesEx.require(!model.trim().equalsIgnoreCase("go"),"E_AI_MODEL: go 是套餐名，请选择具体模型 ID");FilesEx.require(model.trim().length()>0&&limit>=128&&limit<=8192,"E_AI_CONFIG: 填写模型，输出上限为128至8192");SharedPreferences.Editor e=p.edit().putString("endpoint",url.trim()).putString("model",model.trim()).putInt("limit",limit);if(secret.length()>0){Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());e.putString("key",Base64.encodeToString(Signing.concat(c.getIV(),c.doFinal(secret.getBytes("UTF-8"))),2));}FilesEx.require(e.commit(),"E_AI_SETTINGS");}
 public void clear(){p.edit().remove("key").commit();}
}
